  tools.exec_command({cmd:"rg -n \"type authContext|authContext|newClusterSession|teleportClusterClient\" lib/kube/proxy",workdir:"/app",max_output_tokens:12000}),
  tools.exec_command({cmd:"rg --files lib/kube/proxy | rg '(_test\\.go$|forwarder\\.go$)'",workdir:"/app",max_output_tokens:4000})
]); for (const x of r) text(x);

const r = await Promise.allSettled([
  tools.exec_command({cmd:"grep -R -n -E 'type authContext|authContext|newClusterSession|teleportClusterClient' lib/kube/proxy --include='*.go'",workdir:"/app",max_output_tokens:14000}),
  tools.exec_command({cmd:"find lib/kube/proxy -maxdepth 1 -type f -name '*.go' -print",workdir:"/app",max_output_tokens:4000})
]); for (const x of r) text(x);

