		s.teleportCluster.serverID = endpoint.serverID
		conn, err := s.teleportCluster.DialWithContext(ctx, network, addr)
		if err != nil {
			errs = append(errs, err)
			continue
		}
		return conn, nil
	}
	return nil, trace.NewAggregate(errs...)
